def bandwidth_calculate(efficiency,efficiency_condition,wavelength):

    len_wavelength = len(wavelength)

    for len_w in range(len_wavelength):

        if (efficiency[len_w] >= efficiency_condition):

            max_wavelength = wavelength[len_w]

            break

        else:

            max_wavelength = 0

    for len_w in range(len_wavelength):
        
        if (efficiency[len_wavelength-len_w-1] >= efficiency_condition):

            min_wavelength = wavelength[len_wavelength-len_w-1]

            break

        else:

            min_wavelength = 0

    bandwidth = max_wavelength-min_wavelength

    return bandwidth

def center_wavelength_calculate(efficiency,wavelength):

    len_wavelength = len(wavelength)

    efficiency_0 = -100

    for len_w in range(len_wavelength):

        if (efficiency[len_w] >= efficiency_0):

            max_wavelength = wavelength[len_w]
            efficiency_0 = efficiency[len_w]

    return max_wavelength

def run_sim(path,filename):

    with lumapi.FDTD() as fdtd:

        fdtd.load(path+"\\"+filename+".fsp")
        fdtd.run()

