    lsf_file.write('fiber_angle = 10;\n')
    lsf_file.write('fiber_cladding_radius = 62.5*um;\n')
    lsf_file.write('fiber_core_radius = 4.1*um;\n')
    lsf_file.write('fiber_core_index = 1.4703;\n')
    lsf_file.write('fiber_gap = 5*um;\n')
