    lsf_file.write('set("y span",width-10*um);\n')
    lsf_file.write('set("theta",-fiber_angle);\n')
    lsf_file.write('set("rotation offset",fiber_core_radius*sin(fiber_angle/180*pi)*3);\n')
    lsf_file.write('set("center wavelength",center_wavelength);\n')
    lsf_file.write('set("wavelength span",wavelength_span);\n')
    lsf_file.write('set("mode selection",4);\n')
    lsf_file.write('set("selected mode number",%d);\n'%mode_number)
    lsf_file.write('setglobalmonitor("frequency points",frequency_points);\n')
    lsf_file.write('addpower;\n')
    lsf_file.write('set("name","power_monitor_output");\n')
    lsf_file.write('set("simulation type",1);\n')
    lsf_file.write('set("monitor type",7);\n')
    lsf_file.write('set("x",grating_x_2+(waveguide_thickness+TOX_thickness+fiber_gap+source_y)*sin(fiber_angle/180*pi)+fiber_x);\n')
    lsf_file.write('set("x span",fiber_core_radius*6);\n')
    lsf_file.write('set("z",waveguide_thickness+TOX_thickness+fiber_gap+source_y);\n')
    lsf_file.write('set("y",0);\n')
    lsf_file.write('set("y span",width-10*um);\n')

    lsf_file.close()

    with lumapi.FDTD() as fdtd:

        fdtd.feval(path+"\\"+filename+".lsf")
        fdtd.save(path+"\\"+filename+".fsp")

