def SOI_parallel_grating_coupler_2d(path,filename,fiber_x):

    lsf_file = open(path+"\\"+filename+".lsf","w+")

    lsf_file.write('deleteall;\n')
    lsf_file.write('um = 1e-6;\n')
    lsf_file.write('BOX_thickness = 2*um;\n')
