    lsf_file.write('addstructuregroup;\n')
    lsf_file.write('set("name","grating_2");\n')
    lsf_file.write('addstructuregroup;\n')
    lsf_file.write('set("name","fiber");\n')
    lsf_file.write('position_x = 0;\n')
