    lsf_file.write('    position_x = position_x+(1-fill_factor)*grating_period;\n')
    lsf_file.write('    \n')
    lsf_file.write('    addring;\n')
    lsf_file.write('    set("name","teeth_"+num2str(n));\n')
    lsf_file.write('    set("material",SiN_mat);\n')
    lsf_file.write('    set("x",taper_waveguide_length);\n')
