    lsf_file.write('    set("outer radius",position_x+taper_waveguide_length+fill_factor*grating_period);\n')
    lsf_file.write('    set("theta start",-ring_theta+180);\n')
    lsf_file.write('    set("theta stop",ring_theta+180);\n')
    lsf_file.write('    addtogroup("grating_1");\n')
